5:   --blue: #1677ff;
6:   --sky: #eaf4ff;
7:   --ink: #172b4d;
8:   --muted: #62748a;
9:   --line: #dce7f2;
10:   --white: #fff;
11:   --shadow: 0 18px 45px rgba(16, 42, 67, .12);
12: }
