14: * { box-sizing: border-box; }
15: html { scroll-behavior: smooth; }
16: body { margin: 0; color: var(--ink); background: #f8fbff; font: 16px/1.7 'DM Sans', sans-serif; }
17: .container { width: min(1120px, calc(100% - 40px)); margin: auto; }
18: .top-bar { position: sticky; top: 0; z-index: 10; background: rgba(255,255,255,.92); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
19: .top-bar .container { min-height: 74px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
20: .logo { color: var(--navy); font-size: 1.35rem; font-weight: 700; letter-spacing: -.04em; }
21: .top-nav { display: flex; flex-wrap: wrap; gap: 26px; }
22: a { color: inherit; text-decoration: none; }
23: .top-nav a { color: var(--muted); font-size: .92rem; font-weight: 600; transition: color .2s; }
24: .top-nav a:hover, .top-nav a:focus-visible { color: var(--blue); }
25: .hero { padding: 120px 0 135px; color: var(--white); background: radial-gradient(circle at 85% 20%, #43a8ff 0, transparent 30%), linear-gradient(125deg, #102a43, #1261a0); }
26: .hero h1 { max-width: 700px; margin: 0 0 18px; font: 700 clamp(2.5rem, 6vw, 4.7rem)/1.08 'Playfair Display', serif; letter-spacing: -.04em; }
27: .hero p { max-width: 570px; margin: 0 0 32px; color: #dceeff; font-size: 1.15rem; }
28: .cta-btn, button { display: inline-block; border: 0; border-radius: 9px; padding: 13px 22px; color: var(--white); background: var(--blue); font: 600 1rem 'DM Sans', sans-serif; cursor: pointer; transition: transform .2s, box-shadow .2s, background .2s; }
29: .cta-btn:hover, button:hover { background: #075dcc; box-shadow: 0 10px 20px rgba(22,119,255,.25); transform: translateY(-2px); }
30: section { padding: 88px 0; }
31: h2 { margin: 0 0 12px; color: var(--navy); font: 700 clamp(2rem, 4vw, 3rem)/1.2 'Playfair Display', serif; }
32: .about { background: var(--white); }
33: .about-grid, .contact-grid { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 58px; margin-top: 34px; }
34: .about-grid p { color: var(--muted); }
35: .about-img { width: 100%; border-radius: 18px; box-shadow: var(--shadow); }
36: .catalog { background: var(--sky); }
37: .subtitle { margin: 0 0 30px; color: var(--muted); }
38: .product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
39: .product-card { overflow: hidden; border: 1px solid var(--line); border-radius: 16px; background: var(--white); box-shadow: 0 8px 24px rgba(16,42,67,.06); transition: transform .2s, box-shadow .2s; }
40: .product-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); }
41: .product-card img { display: block; width: 100%; height: 180px; object-fit: cover; }
42: .product-card > div { padding: 20px; }
43: .product-card h3 { margin: 0 0 7px; color: var(--navy); }
44: .product-card p { margin: 0; color: var(--muted); }
45: .contact-form { display: grid; gap: 13px; }
46: input, textarea { width: 100%; border: 1px solid var(--line); border-radius: 8px; padding: 14px 15px; color: var(--ink); background: var(--white); font: inherit; resize: vertical; }
47: input:focus, textarea:focus { outline: 3px solid rgba(22,119,255,.2); border-color: var(--blue); }
48: .contact-info { padding: 28px; border-radius: 16px; color: var(--muted); background: var(--sky); }
49: .contact-info p { margin: 0 0 18px; }
50: .contact-info strong { color: var(--navy); }
51: .form-status { margin-top: 16px; color: var(--blue); font-weight: 600; }
52: .footer { padding: 25px 0; color: #bcd2e5; background: var(--navy); text-align: center; }
53: .footer p { margin: 0; font-size: .9rem; }
54: @media (max-width: 760px) {
55:   .top-bar .container { align-items: flex-start; flex-direction: column; padding: 16px 0; }
56:   .top-nav { gap: 12px 18px; }
57:   .hero { padding: 82px 0 95px; }
58:   section { padding: 62px 0; }
59:   .about-grid, .contact-grid, .product-grid { grid-template-columns: 1fr; gap: 25px; }
60:   .about-grid { margin-top: 22px; }
61: }
62: @media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }
